<template>
    <transition appear
        name="animate__animated animate__bounce" 
        enter-active-class="animate__fadeInLeft"
        leave-active-class="animate__fadeOutRight">
        <li class="item-style">  
            <label>
                <div class="task-name">
                    <input 
                        type="checkbox" 
                        :checked="itemData.isChecked" 
                        @change="changeCheckItem(itemData.id)" 
                        v-show="!itemData.isEdit"/>
                    <!-- 不建议这样写，不应该去改变props里的值 ,虽然是间接性的-->
                    <!-- <input type="checkbox" :v-model="itemData.isChecked"> -->
                    <span v-show="!itemData.isEdit">{{ itemData.taskName }}</span>
                    <input 
                        type="text" 
                        :value="itemData.taskName" 
                        v-show="itemData.isEdit"  
                        @blur="handlerBlur(itemData,$event)"
                        ref="inputTitle"/>
                </div>
            </label> 
            <div>
                <button class="edit-btn" @click="editBtn(itemData)">编辑</button>
                <button class="delete-btn" @click="deleteBtn(itemData.id)">删除</button>
            </div>
        </li>
    </transition>
    
</template>

<script>
    import pubsub from "pubsub-js";
    import "animate.css";

    export default {
        name: "NoteItem",
        props:["itemData"],
        data() {
            return {}
        },
        computed: {
            getEditext(){
                return this.itemData.isEdit ? "完成" : "编辑"
            },
        },
        methods:{
            changeCheckItem(id){
                console.log("勾选",id);
                 //消息订阅，发送
                pubsub.publish("checkItem",id)
            },
            deleteBtn(id){
                console.log("删除id",id)
                if(confirm("确定删除吗？")) {
                    //消息订阅，发送
                    pubsub.publish("deleteItem",id)
                }
            },
            editBtn(itemData) {
                //Object.hasOwn(this.itemData,"isEdit")
                if (itemData.hasOwnProperty("isEdit")) {
                    itemData.isEdit = true
                } else {
                    this.$set(itemData,"isEdit",true)
                }
                this.$nextTick(function() {
                    this.$refs.inputTitle.focus()
                })
                console.log("item编辑数据",this.itemData)
            },

            //输入框失去焦点回调
            handlerBlur(itemData,e) {
                itemData.isEdit =  false
                if (!e.target.value.trim()) {
                    alert("输入数据不能为空")
                    return
                }
                itemData.taskName = e.target.value
                console.log("item编辑失去焦点",itemData, itemData.id, e.target.value)
            }
        }
    }
</script>
<style scoped>
    .item-style {
        height: 30px;
        display: flex;
        flex-direction: row;
        justify-content: space-between;
        align-items: center;
        padding: 5px 9px;
        border-bottom: 1px solid #ccc;
    }
    .item-style:last-child {
        border-bottom: none;
    }

    .item-style:hover {
        background-color: #ccc;
    }

    .delete-btn {
        width:60px;
        height: 30px;
        font-size: 12px;
        color: white;
        background-color: red;
        border: 2px solid blue;
        border-radius: 5px;
        cursor: pointer;
        margin-left: 5px;
        display: none;
    }
    li:hover .delete-btn {
        display: inline-block;
    }

    .delete-btn:hover {
        background-color: #66b1ff;
    }

    /* 鼠标点击效果 */
    .delete-btn:active {
        background-color: #ccc;
    }

    span {
        margin-left: 5px;
    }

    .edit-btn {
        width:60px;
        height: 30px;
        font-size: 12px;
        color: white;
        background-color: skyblue;
        border-radius: 5px;
        border: none;
        cursor: pointer;
        display: none;
    }

    li:hover .edit-btn {
        display: inline-block;
    }

    .task-name {
        height: 100%;

    }
</style>