<template>
    <div v-show="totalCount" class="footer-style" >
        <!-- <input type="checkbox" :checked="isAll">  -->
         <div>
            <input type="checkbox" v-model="isAll"> 
            <span>已完成{{selecteCount}} / 全部{{totalCount}}</span>
         </div>
        <button v-show="selecteCount" @click="clearData">清除已完成数据</button>
    </div>
</template>
<script>
    export default {
        name: "TotalFooter",
        props:["dataList"],
        data() {
            return {
                
            }
        },
        computed:{
            totalCount(){
                return this.dataList.length
            },
            selecteCount() {
                console.log("选择数量")
                return this.dataList.reduce((total,item) => {
                    console.log(total,item)
                    return total + (item.isChecked ? 1 : 0)
                },0)
            },
            // isAll(){
            //     return this.totalCount > 0 && this.totalCount === this.selecteCount
            // }
            isAll: {
                get() {
                    return this.totalCount > 0 && this.totalCount === this.selecteCount
                },
                set(value) {
                    console.log(value)
                     //全局事件总线,发送数据
                    this.$bus.$emit("checkedAll",value)
                }
            }
        },
        methods: {
            clearData(){
                if(confirm("确定清除吗？")) {
                    //this.clearFinishData()
                    //全局事件总线,发送数据
                    this.$bus.$emit("clearFinishData")
                }
            }
        }
    }
</script>

<style scoped>
    .footer-style {
        height: 45px;
        display: flex;
        flex-direction: row;
        justify-content: space-between;
        align-items: center;
        margin-top: 15px;
    }
    span {
        margin-left: 10px;
    }

    div button {
        color: white;
        background-color: red;
        border-radius: 3px;
        border: none;
        padding: 5px;
    }

</style>