<template>
    <div>
        <input 
            class="task-input" type="text" 
            placeholder="请输入任务名称，按回车结束" 
            @keyup.enter="inputConfirm"
            v-model.trim="inputText">
    </div>
</template>

<script>
    import { nanoid } from 'nanoid';
    export default {
        name: "InputHead",
        beforeDestroy() {
            //解绑自定义事件
            this.$off("addData")
        },
        data() {
            return {
                inputText:""
            }
        },
        methods: {
            inputConfirm(e) {
                if (this.inputText === "") {
                    alert("输入不能为空")
                    return
                }
                const itemData = {id:nanoid(),taskName:this.inputText,isChecked:false}
                //发送自定义事件数据
                this.$emit("addData",itemData)
                this.inputText = ""
            }
        }
    }
</script>

<style scoped>

    .task-input {
        width: 100%;
        padding: 8px 5px;
        box-sizing: border-box;
        border: 1px solid #ccc; /* 建议加上边框，看起来更精致 */
        border-radius: 5px;
    }

    .task-input:focus {
        outline: none;
        border: 1px solid skyblue;
        box-shadow: 0 0 8px skyblue;
        border-radius: 5px;
    }

</style>