<template>
    <div class="app-style">
        <!-- 绑定自定义事件 -->
        <InputHead 
            @addData="addData"/>

        <NoteList 
            v-show="dataList.length" 
            :dataList="dataList"/>

        <TotalFooter 
            :dataList="dataList"/>
    </div>
</template>

<script>
    import InputHead from "./components/InputHead.vue"
    import NoteList from "./components/NoteList.vue"
    import TotalFooter from "./components/TotalFooter.vue"
    import pubsub from "pubsub-js";

    export default {
        name:"App",
        mounted() {
            //读取缓存数据
            const list =  localStorage.getItem("dataList")
            console.log("读取本地数据",list);
            if (list) {
                this.dataList = JSON.parse(list)
            }   
            
            //全局事件总线，清除已完成数据
            this.$bus.$on("clearFinishData", ()=>{
                console.log("全局事件总线，清除已完成数据")
                this.dataList = this.dataList.filter(item => !item.isChecked)
            })
            
            //全局事件总线，全勾选
            this.$bus.$on("checkedAll", (isChecked) => {
                console.log("全局事件总线，全勾选",isChecked)
                this.dataList.forEach(item => item.isChecked = isChecked)
            })

            //消息订阅，勾选item
            this.checkId = pubsub.subscribe("checkItem", (_,data) => {
                console.log("消息订阅，勾选item", data)
                this.dataList.forEach(item => {
                    if (item.id === data) {
                        item.isChecked = !item.isChecked
                    }
                })
            })

            //消息订阅，删除数据
            this.deleteId = pubsub.subscribe("deleteItem", (_,data)=>{
                console.log("消息订阅，删除数据",data)
                this.dataList = this.dataList.filter(item => item.id !== data)
            })

        },
        beforeDestroy() {
            //全局事件总线 解绑
            this.$bus.$off(["clearFinishData","checkedAll"])
            //取消消息订阅
            pubsub.unsubscribe(this.checkId);
            pubsub.unsubscribe(this.deleteId);
        },
        components:{
          InputHead,
          NoteList,
          TotalFooter
        },
        data() {
            return {
                //数据源
                dataList:[]
            }
        },
        methods: {
            //自定义事件获取添加数据
            addData(itemData){
                console.log("收到添加数据",itemData)
                this.dataList.unshift(itemData)
            },
        },
        watch: {
            //监听列表数据变化，并保存在本地
            dataList:{
                deep:true,
                handler(newValue,oldValue){
                    console.log("列表数据变化",newValue,oldValue); 
                     localStorage.setItem("dataList",JSON.stringify(newValue))
                }
            }
        }
    }
</script>

<style scoped>
    .app-style {
        width: 600px;
        background-color: white;
        border: 2px solid #cccccc;
        border-radius: 3px;
        display: flex;
        flex-direction: column;
        padding: 15px;
    }
</style>


